parameters.responseBody:
={{
  JSON.stringify({
    choices: [
      {
        message: {
          role: "assistant",
          content: ($json.output || "")
        }
      }
    ],
    sessionId: ($node["Prepare - Chat Payload"].json.sessionId || "")
  })
}}

assignments.value:
={{
  (() => {
    const last = ($json.body.messages || []).filter(m => m.role === 'user').pop();
    return last ? String(last.content) : '';
  })()
}}

={{
  (() => {
    if ($json.headers && $json.headers['x-openwebui-chat-id']) {
        return 'webui-chat-' + $json.headers['x-openwebui-chat-id'];
    }
    if ($json.body && $json.body.session_id) {
        return $json.body.session_id;
    }
    return 'auto-session-' + (new Date().getTime().toString(36));
  })()
}}

={{
  (() => {
    const allowed = ['gpt-4.1-mini','gpt-4.1','UNLa_Asistente_Virtual_Académico'];
    const inc = ($json.body && $json.body.model) ? String($json.body.model).trim() : '';
    const incNorm = inc.toLowerCase();

    if (allowed.map(a => a.toLowerCase()).includes(incNorm)) return inc;

    if (incNorm.includes('unla')) return 'gpt-4.1-mini';

    if (incNorm.includes('arena')) return 'gpt-4.1-mini';

    return 'gpt-4.1-mini';
  })()
}}
